export const ALL_SERVICES: ServiceItem[] = CATEGORIES.flatMap((c) => c.services);

export function getServiceBySlug(categorySlug: string, serviceSlug: string): ServiceItem | undefined {
  const category = CATEGORIES.find((c) => c.slug === categorySlug);
  return category ? category.services.find((s) => s.slug === serviceSlug) : undefined;
}

export function getCategoryBySlug(categorySlug: string): ServiceCategory | undefined {
  return CATEGORIES.find((c) => c.slug === categorySlug);
}
